  static Object? ordered(Object? value) {
    if (value is Map) {
      final keys = value.keys.cast<String>().toList()..sort();
      return {for (final k in keys) k: ordered(value[k])};
    }
    if (value is List) {
      return value.map(ordered).toList();
    }
    return value;
  }

  static bool matches(String key, Map evidence) {
    final p = expected[key];
    if (p is! Map ||
        evidence['financialFactsStored'] != false ||
        evidence['fullStatementCollected'] == true ||
        evidence['notesVerified'] == true ||
        evidence['noData'] == true ||
        evidence['collectionComplete'] == true) {
      return false;
    }
    final e = Map<String, dynamic>.from(evidence);
    for (final k in [
      'negativeCacheManifestSha256',
      'networkRequests',
      'apiCalls',
      'collectionComplete',
      'readFromPinnedCache',
    ]) {
      e.remove(k);
    }
    if (!p.containsKey('noData') && e['noData'] == false) {
      e.remove('noData');
    }
    return jsonEncode(ordered(e)) == jsonEncode(ordered(p));
  }
